'use client';

import React from 'react';
import { LAND_PATH, MAP_H, MAP_W, REGIONS } from './regionMapData';

// Recognisable world map (country outlines) with Digital Den's approved countries/regions
// filled in purple and subtle animated turquoise connection lines from the Montenegro hub
// (Home Page notes, section 09). Shapes are pre-generated by scripts/build-region-map.mjs.

// Label placement per region (SVG units): kept clear of each other in crowded Europe.
const LABEL: Record<string, { dx: number; dy: number; anchor: 'start' | 'end' | 'middle' }> = {
  montenegro: { dx: 10, dy: 18, anchor: 'start' },
  'western-balkans': { dx: 12, dy: -12, anchor: 'start' },
  'united-states': { dx: 0, dy: -18, anchor: 'middle' },
  benelux: { dx: -10, dy: -10, anchor: 'end' },
  jordan: { dx: 10, dy: 16, anchor: 'start' },
};

export default function RegionMap({ className = '' }: { className?: string }) {
  const hub = REGIONS.find((r) => r.hub)!;
  // No arc to the Western Balkans: Montenegro is part of it, so the line would be a tiny stub.
  const spokes = REGIONS.filter((r) => !r.hub && r.id !== 'western-balkans');

  return (
    <svg
      viewBox={`0 0 ${MAP_W} ${MAP_H}`}
      className={className}
      role="img"
      aria-label={`World map highlighting Digital Den's presence: ${REGIONS.map((r) => r.name).join(', ')}`}
    >
      <defs>
        <linearGradient id="dd-arc" x1="0" x2="1" y1="0" y2="0">
          <stop offset="0%" stopColor="#38bdf8" stopOpacity="0.2" />
          <stop offset="100%" stopColor="#5eead4" stopOpacity="0.95" />
        </linearGradient>
        <filter id="dd-glow" x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation="3" />
        </filter>
        <style>{`
          @keyframes dd-arc-flow { to { stroke-dashoffset: -40; } }
          @keyframes dd-pulse { 0% { r: 4; opacity: .7 } 100% { r: 22; opacity: 0 } }
          .dd-arc { stroke-dasharray: 6 14; animation: dd-arc-flow 1.6s linear infinite; }
          .dd-pulse { animation: dd-pulse 2.4s ease-out infinite; }
          @media (prefers-reduced-motion: reduce) { .dd-arc, .dd-pulse { animation: none; } }
        `}</style>
      </defs>

      {/* All other countries: quiet outlines so the geography reads at a glance */}
      <path d={LAND_PATH} fill="rgba(255,255,255,0.055)" stroke="rgba(255,255,255,0.16)" strokeWidth={0.5} strokeLinejoin="round" />

      {/* Approved countries/regions in purple */}
      {REGIONS.map((r) => (
        <g key={r.id}>
          <path d={r.d} fill={r.hub ? '#c084fc' : '#a855f7'} opacity={0.35} filter="url(#dd-glow)" />
          <path d={r.d} fill={r.hub ? '#c084fc' : '#a855f7'} fillOpacity={r.hub ? 0.95 : 0.8} stroke="#e9d5ff" strokeWidth={0.6} strokeLinejoin="round" />
        </g>
      ))}

      {/* Connection lines from the hub */}
      {spokes.map((r) => {
        const mx = (hub.x + r.x) / 2;
        const lift = Math.min(90, Math.hypot(r.x - hub.x, r.y - hub.y) * 0.35);
        const d = `M${hub.x},${hub.y} Q${mx},${Math.min(hub.y, r.y) - lift} ${r.x},${r.y}`;
        return (
          <g key={r.id}>
            <path d={d} fill="none" stroke="rgba(94,234,212,0.18)" strokeWidth={1.2} />
            <path d={d} fill="none" stroke="url(#dd-arc)" strokeWidth={1.6} strokeLinecap="round" className="dd-arc" />
          </g>
        );
      })}

      {/* Markers + labels (labels hidden on small screens; names are listed below the map there) */}
      {REGIONS.map((r) => {
        const l = LABEL[r.id];
        return (
          <g key={r.id}>
            {r.hub && <circle cx={r.x} cy={r.y} r={4} fill="none" stroke="#e9d5ff" strokeWidth={1.2} className="dd-pulse" />}
            <circle cx={r.x} cy={r.y} r={r.hub ? 4 : 3} fill="#ffffff" />
            <text
              x={r.x + l.dx}
              y={r.y + l.dy}
              textAnchor={l.anchor}
              className="hidden md:block"
              fill="#ffffff"
              fontSize={r.hub ? 15 : 13}
              fontWeight={r.hub ? 700 : 600}
              style={{ paintOrder: 'stroke', stroke: 'rgba(11,11,12,0.85)', strokeWidth: 4, fontFamily: 'var(--font-plus-jakarta), sans-serif' }}
            >
              {r.name}
            </text>
          </g>
        );
      })}
    </svg>
  );
}
